    fn typescript_detection_rule_union_matches_the_rust_enum() {
        let declarations = read_repo_file("packages/napi/index.d.ts");
        let union = declarations
            .split("export type DetectionRule =")
            .nth(1)
            .and_then(|rest| rest.split("\n\n").next())
