// Hand-maintained — NOT regenerated by `napi build`. The auto-generated NAPI
// function signatures (extractAll, JsExtractOptions, etc.) live in binding.d.ts,
// rebuilt fresh from the Rust #[napi] annotations on every `pnpm run build:napi`.
// This file re-exports those plus the hand-written shape of the JSON string
// each function resolves to (ExtractionOutput et al. — opaque to NAPI-RS's
// codegen since it only sees `Promise<string>` at the FFI boundary).
// Matches crates/core/src/types.rs.
export * from './binding'

export interface InheritedLayer {
  typeName: string
  fileName: string
  omitted: string[]
  htmlElement: string | null
  totalProps: number
  /** For a collapsed source, the names of the props it declares. Absent when the layer's props are expanded. */
  members?: string[]
}

/** An inheritance layer in the canonical JSON: `omitted` is the id of a list in the output's `nameLists`. */
export interface InheritedLayerRef extends Omit<InheritedLayer, 'omitted' | 'members'> {
  omitted: NameListId
  /** The id of a list in `nameLists`, for a collapsed source. */
  members?: NameListId
}

export interface PropParent {
  name: string
  fileName: string
}

export interface DefaultValue {
  value: string
  computed: boolean
}

export type OpaqueReason =
  | { type: 'conditionalType' }
  | { type: 'mappedType' }
  | { type: 'moduleAugmentation' }
  | { type: 'runtimeDependent'; functionName: string }
  | { type: 'unresolvableImport'; specifier: string }
  | { type: 'pandaCodegenMissing' }
  | { type: 'depthExceeded' }
  | { type: 'indexedAccess'; expression: string }
  | { type: 'templateLiteral'; expression: string }

export interface FunctionParam {
  /** `null` for a destructured parameter. */
  name: string | null
  type: PropType
  /** The parameter is written `name?: T`. Absent when false. */
  optional?: boolean
  /** The parameter is the rest parameter `...name: T[]`; `type` is the array type as written. Absent when false. */
  rest?: boolean
}

export interface ObjectField {
  name: string
  propType: PropType
  required: boolean
  description: string
  /** Written `readonly name: T`. Absent when false. */
  readonly?: true
  /** Set for an index signature `[name: K]: T`: the key type `K`, with `name` the key parameter and `propType` the value. */
  indexKey?: PropType
}

export type PropType =
  | { kind: 'string' }
  | { kind: 'number' }
  | { kind: 'boolean' }
  | { kind: 'null' }
  | { kind: 'undefined' }
  | { kind: 'any' }
  | { kind: 'never' }
  | { kind: 'unknown' }
  | { kind: 'void' }
  | { kind: 'reactNode' }
  | { kind: 'cssProperties' }
  | { kind: 'elementType' }
  | { kind: 'sxProps' }
  | { kind: 'stringLiteral'; value: string }
  | { kind: 'numberLiteral'; value: number }
  | { kind: 'boolLiteral'; value: boolean }
  | { kind: 'union'; members: PropType[] }
  | { kind: 'intersection'; members: PropType[] }
  | { kind: 'array'; element: PropType }
  | { kind: 'tuple'; elements: PropType[] }
  | { kind: 'readonly'; element: PropType }
  | { kind: 'object'; fields: ObjectField[] }
  | { kind: 'named'; name: string; args: PropType[] }
  | { kind: 'function'; typeParams: string[]; params: FunctionParam[]; returnType: PropType }
  | { kind: 'ref'; name: string; element: string | null }
  | { kind: 'htmlAttributes'; element: string; omitted: string[] }
  | { kind: 'literalUnion'; members: string[]; hasDefault: boolean }
  | { kind: 'opaque'; raw: string; reason: OpaqueReason }

export interface ParsedProp {
  name: string
  type: PropType
  required: boolean
  defaultValue: DefaultValue | null
  description: string
  tags: Record<string, string>
  parent: PropParent | null
  declarations: PropParent[]
  /**
   * Why part of this prop's type is `opaque`: the kinds of reason (`conditionalType`, `mappedType`, `indexedAccess`, …),
   * each once, in the order the type holds them. Absent when the resolver evaluated the type in full. A name left as an
   * unexpanded reference is not listed; its diagnostic says so.
   */
  degradedBy?: string[]
}

/**
 * A prop's key in a `props` table: 16 hex digits hashed from the prop's JSON, so the same prop has the same id in every
 * output and update of a build. Opaque: never store one beyond the output it came from.
 */
export type PropId = string

/**
 * A prop set's key in a `propSets` table: the props one declaring type contributes to a component, as prop name to
 * `PropId`. Components that inherit the type share the set. Opaque like `PropId`.
 */
export type PropSetId = string

/** A list's key in a `nameLists` table: the prop names an `Omit` removed at one inheritance layer. Opaque like `PropId`. */
export type NameListId = string

/** Prop name to the prop's id in the output's (or update's) `props` table. */
export type PropSet = Record<string, PropId>

export interface ComponentEntry {
  displayName: string
  filePath: string
  description: string
  /**
   * The ids of the prop sets, in the output's (or update's) `propSets` table, that together hold the component's
   * props. A prop name is in one set.
   */
  props: PropSetId[]
  inheritance: InheritedLayerRef[]
  /** Prop name to the prop's id in the output's (or update's) `props` table. */
  notableInherited: Record<string, PropId>
  discriminantProp: string | null
  composes: string[]
  tags: Record<string, string>
  methods: []
  /** The rule that recognized the component; `typedFunctionExpression` and `wrapperTypeArgument` are inferred. */
  detectedBy: DetectionRule
  /** Whether its module exports it, directly or as a sub-component attached to an exported component. */
  exported: boolean
}

export type DetectionRule =
  | 'fcAnnotation'
  | 'forwardRef'
  | 'forwardRefExoticDecl'
  | 'hocWrapper'
  | 'classComponent'
  | 'functionDeclaration'
  | 'anonymousDefaultExport'
  | 'attachedSubComponent'
  | 'typedFunctionExpression'
  | 'wrapperTypeArgument'
  | 'importedMemberAlias'
  | 'memoExoticDecl'
  | 'taggedFactory'
  | 'factoryResult'

export interface EnumEntry {
  name: string
  value: string | number | boolean
  description: string
}

export interface Diagnostic {
  severity: 'error' | 'warning' | 'info'
  message: string
  file: string | null
  line: number | null
  column: number | null
  help: string | null
  code: string
  /** Keys of the components whose resolution reported this diagnostic; absent for file- and run-level ones. */
  affects?: string[]
}

/**
 * A diagnostic as the canonical JSON writes it: `affects` is the id of a list in the output's (or update's)
 * `nameLists` table, absent when the diagnostic affects no component.
 */
export interface WireDiagnostic extends Omit<Diagnostic, 'affects'> {
  affects?: NameListId
}

/** What `initializeSessionIndex` resolves to: where each component lives and the run's diagnostics, without props. */
export interface SessionIndex {
  schemaVersion: number
  components: Record<string, { filePath: string; displayName: string }>
  nameLists: Record<NameListId, string[]>
  diagnostics: WireDiagnostic[]
}

export interface ExtractionStats {
  componentsExtracted: number
  componentsSkipped: number
  filesParsed: number
  dtsFilesParsed: number
  dtsCacheHits: number
  durationMs: number
  tier1Count: number
  tier3Count: number
  opaqueCount: number
}

/** A prop as react-docgen-typescript documents it (`sessionDocgenInfo`). */
export interface RdtProp {
  name: string
  /** A literal union is `{ name: 'enum', raw, value }`; any other type is `{ name }`, its text. */
  type: { name: string; raw?: string; value?: Array<{ value: string }> }
  required: boolean
  defaultValue: { value: string; computed: boolean } | null
  description: string
  parent: { name: string; fileName: string } | null
}

/** A component as react-docgen-typescript documents it: the `__docgenInfo` Storybook converts to argTypes. */
export interface RdtComponentDoc {
  displayName: string
  description: string
  props: Record<string, RdtProp>
  methods: []
  tags: Record<string, string>
  composes: string[]
}

export interface ExtractionOutput {
  /** The shape of this JSON (ADR 0017). A reader checks it is a version it reads. */
  schemaVersion: number
  components: Record<string, ComponentEntry>
  /** Every distinct prop the components refer to, written once (ADR 0009). */
  props: Record<PropId, ParsedProp>
  /** Every prop set the components refer to, written once (ADR 0018). */
  propSets: Record<PropSetId, PropSet>
  /** Every omitted-names list the components' inheritance layers refer to, written once (ADR 0018). */
  nameLists: Record<NameListId, string[]>
  enums: Record<string, EnumEntry[]>
  diagnostics: WireDiagnostic[]
  stats: ExtractionStats
}

export interface IncrementalUpdate {
  /** The shape of this JSON, as in `ExtractionOutput`. */
  schemaVersion: number
  /** The session revision this update produced; drop an update older than one already applied. */
  revision: number
  /** Components re-resolved by this change, in the same order as `updatedKeys`. */
  updatedComponents: ComponentEntry[]
  /** Every prop `updatedComponents` refer to. Merge it into the output's table; ids nothing refers to can be dropped. */
  props: Record<PropId, ParsedProp>
  /** The prop sets `updatedComponents` refer to; merge like `props`. */
  propSets: Record<PropSetId, PropSet>
  /** The omitted-names lists `updatedComponents` refer to; merge like `props`. */
  nameLists: Record<NameListId, string[]>
  /** The output key each updated component is published under: a bare name, or `Name (file)` when disambiguated. */
  updatedKeys: string[]
  /** Output keys that no longer exist: the component was renamed, deleted, or stopped being a component. */
  removedKeys: string[]
  /** Diagnostics this revision no longer has; `diagnostics` holds the ones it added. */
  removedDiagnostics: WireDiagnostic[]
  affectedFiles: string[]
  diagnostics: WireDiagnostic[]
  durationMs: number
}

